import React, { useRef, useState } from 'react';
import { X, Upload, User, Save } from 'lucide-react';
import { UserSettings } from '../types';

interface SettingsDialogProps {
  currentSettings: UserSettings | null;
  onSave: (settings: UserSettings) => void;
  onClose: () => void;
}

const SettingsDialog: React.FC<SettingsDialogProps> = ({ currentSettings, onSave, onClose }) => {
  const [displayName, setDisplayName] = useState(currentSettings?.displayName || '');
  const [avatarBase64, setAvatarBase64] = useState<string | null>(currentSettings?.avatarBase64 || null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = () => {
        if (typeof reader.result === 'string') {
           // Basic constraint: check if string is too massive for localStorage, 
           // though modern browsers handle ~5MB well.
           // Ideally we resize, but for this demo we assume reasonable inputs.
           setAvatarBase64(reader.result);
        }
      };
      reader.readAsDataURL(file);
    }
  };

  const handleSave = () => {
    onSave({
      displayName: displayName || 'Creator',
      avatarBase64
    });
    onClose();
  };

  return (
    <div className="fixed inset-0 z-[60] flex items-center justify-center p-4 bg-black/80 backdrop-blur-sm">
      <div className="bg-[#111] border border-white/10 w-full max-w-md rounded-3xl p-6 shadow-2xl relative overflow-hidden">

        {/* Header */}
        <div className="flex items-center justify-between mb-8">
          <h2 className="text-2xl font-bogle text-white tracking-wide">Creator Settings</h2>
          <button onClick={onClose} className="p-2 bg-white/5 rounded-full hover:bg-white/10 transition-colors">
            <X className="w-5 h-5 text-white/70" />
          </button>
        </div>

        <div className="space-y-6">
          {/* Avatar Section */}
          <div className="flex flex-col items-center gap-4">
            <div 
              className="w-24 h-24 rounded-full bg-white/5 border border-white/10 flex items-center justify-center overflow-hidden cursor-pointer group relative"
              onClick={() => fileInputRef.current?.click()}
            >
              {avatarBase64 ? (
                <img src={avatarBase64} alt="Avatar" className="w-full h-full object-cover" />
              ) : (
                <User className="w-8 h-8 text-white/30" />
              )}
              <div className="absolute inset-0 bg-black/50 opacity-0 group-hover:opacity-100 flex items-center justify-center transition-opacity">
                <Upload className="w-6 h-6 text-white" />
              </div>
            </div>
            <button 
                onClick={() => fileInputRef.current?.click()}
                className="text-xs text-white/50 hover:text-white transition-colors uppercase tracking-wider font-medium"
            >
                Change Avatar
            </button>
            <input 
              type="file" 
              ref={fileInputRef} 
              className="hidden" 
              accept="image/*"
              onChange={handleFileChange}
            />
          </div>

          {/* Name Section */}
          <div className="space-y-2">
            <label className="text-xs text-white/40 uppercase tracking-widest font-bold ml-1">Display Name</label>
            <input
              type="text"
              value={displayName}
              onChange={(e) => setDisplayName(e.target.value)}
              placeholder="e.g. Seth Anderson"
              className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-3 text-white focus:outline-none focus:border-white/30 transition-colors"
            />
          </div>
        </div>

        {/* Footer */}
        <div className="mt-8 pt-6 border-t border-white/5">
          <button
            onClick={handleSave}
            className="w-full bg-white text-black font-bold py-3.5 rounded-xl hover:bg-gray-200 transition-colors flex items-center justify-center gap-2"
          >
            <Save className="w-4 h-4" />
            Save Profile
          </button>
        </div>

      </div>
    </div>
  );
};

export default SettingsDialog;

