          case AppView.FEED:
          default:
              return (
                <div className="w-full max-w-[1600px] mx-auto p-4 md:p-6 pb-48 relative z-10">
                    <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4 md:gap-6">
